28	export function formatMoney(cents, currency) {
29	  currency = currency || "USD";
30	  try {
31	    return new Intl.NumberFormat(undefined, {
32	      style: "currency",
33	      currency: currency,
34	    }).format(cents / 100);
35	  } catch (e) {
36	    return "$" + (cents / 100).toFixed(2);
37	  }
38	}
