40	export function normalizeProduct(raw) {
41	  return {
42	    id: String(raw.id),
43	    title: raw.title,
44	    category: raw.category || "",
45	    description: raw.description || "",
46	    priceCents: Number(raw.priceCents) || 0,
47	    currency: raw.currency || "USD",
48	    image: raw.image || "",
49	  };
50	}
