52	let _productsCache = null;
53	const PRODUCTS_URL = "./products.json";
54	
55	export function fetchProducts() {
56	  if (_productsCache) return Promise.resolve(_productsCache);
57	
58	  return fetch(PRODUCTS_URL)
59	    .then((r) => {
60	      if (!r.ok) throw new Error("Failed to load products");
61	      return r.json();
62	    })
63	    .then((data) => {
64	      _productsCache = (Array.isArray(data) ? data : []).map(normalizeProduct);
65	      return _productsCache;
66	    })
67	    .catch((error) => {
68	      console.error("Failed to fetch products:", error);
69	      throw error;
70	    });
71	}
