12	  const io = new IntersectionObserver(
13	    (entries) => {
14	      entries.forEach((en) => {
15	        if (en.isIntersecting) {
16	          en.target.classList.add("is-visible");
17	          io.unobserve(en.target);
18	        }
19	      });
20	    },
21	    { rootMargin: "0px 0px -8% 0px", threshold: 0.08 }
22	  );
23	  els.forEach((el) => {
24	    io.observe(el);
25	  });
26	}
