28	export function formatMoney(cents, currency) {
29	  currency = currency || "USD";
30	  try {
31	    return new Intl.NumberFormat(undefined, {
32	      style: "currency",
33	      currency: currency,
34	    }).format(cents / 100);
35	  } catch (e) {
36	    return "$" + (cents / 100).toFixed(2);
37	  }
38	}
39	
40	export function normalizeProduct(raw) {
41	  return {
42	    id: String(raw.id),
43	    title: raw.title,
44	    category: raw.category || "",
45	    description: raw.description || "",
46	    priceCents: Number(raw.priceCents) || 0,
47	    currency: raw.currency || "USD",
48	    image: raw.image || "",
49	  };
50	}
51	
52	let _productsCache = null;
53	const PRODUCTS_URL = "./products.json";
54	
55	export function fetchProducts() {
56	  if (_productsCache) return Promise.resolve(_productsCache);
57	
58	  return fetch(PRODUCTS_URL)
59	    .then((r) => {
60	      if (!r.ok) throw new Error("Failed to load products");
61	      return r.json();
62	    })
63	    .then((data) => {
64	      _productsCache = (Array.isArray(data) ? data : []).map(normalizeProduct);
65	      return _productsCache;
66	    })
67	    .catch((error) => {
68	      console.error("Failed to fetch products:", error);
69	      throw error;
70	    });
71	}
72	
73	export function escapeHtml(s) {
74	  const d = document.createElement("div");
75	  d.textContent = s;
76	  return d.innerHTML;
77	}
78	
79	export function escapeAttr(s) {
80	  s = s == null ? "" : String(s);
81	  return s
82	    .replace(/&/g, "&amp;")
83	    .replace(/"/g, "&quot;")
84	    .replace(/</g, "&lt;")
85	    .replace(/>/g, "&gt;");
86	}
87	
88	export function addImgFallback(img) {
89	  const parent = img && img.parentElement;
90	  img.onerror = function () {
91	    this.style.display = "none";
92	    if (parent) {
93	      const label = document.createElement("span");
94	      label.className = "img-placeholder";
95	      label.textContent = "Image unavailable";
96	      parent.appendChild(label);
97	    }
98	  };
99	}

